function shortestSubarray(nums, k) {
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + nums[i];
  }
  const deque = new Array(n + 1);
  let head = 0;
  let tail = 0;
  let best = n + 1;
  for (let right = 0; right <= n; right++) {
    while (head < tail && prefix[right] - prefix[deque[head]] >= k) {
      best = Math.min(best, right - deque[head]);
      head++;
    }
    while (head < tail && prefix[deque[tail - 1]] >= prefix[right]) {
      tail--;
    }
    deque[tail] = right;
    tail++;
  }
  return best <= n ? best : -1;
}

