function shortestSubarray(nums, k) {
  let best = -1;
  for (let start = 0; start < nums.length; start++) {
    let sum = 0;
    for (let end = start; end < nums.length; end++) {
      sum += nums[end];
      const length = end - start + 1;
      if (sum >= k && (best === -1 || length < best)) best = length;
    }
  }
  return best;
}

