function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const positive = 0.45 + rand() * 0.2;
    const nums = Array.from({ length: n }, () => (rand() < positive ? pick(0, 100000) : pick(-100000, 0)));
    const k = rand() < 0.15 ? pick(1, 1000000000) : pick(1, 5000000);
    return [nums, k];
  }
  const n = pick(1, 9);
  const span = rand() < 0.3 ? 3 : 12;
  const nums = Array.from({ length: n }, () => pick(-span, span));
  const positive = nums.reduce((sum, v) => sum + Math.max(v, 0), 0);
  const k = pick(1, Math.max(1, positive + 2));
  return [nums, k];
}
